-- Reports: configuration keys and the report catalogue (one row per report screen). Idempotent; admin edits are kept.
INSERT INTO app_settings(key, value, "group", label, type) VALUES
 ('reports.default_format', '"xlsx"'::jsonb, 'reports', 'Default report file format (csv, xlsx, pdf)', 'string'),
 ('reports.max_rows', '50000'::jsonb, 'reports', 'Maximum rows written to a generated report file', 'number'),
 ('reports.default_page_size', '50'::jsonb, 'reports', 'Rows per page when a report is shown on screen', 'number'),
 ('reports.default_range_days', '365'::jsonb, 'reports', 'Days covered when a report is run without a From Date', 'number'),
 ('reports.download_link_ttl_hours', '72'::jsonb, 'reports', 'Validity of report download links (hours)', 'number'),
 ('reports.pdf_page_size', '"A4"'::jsonb, 'reports', 'PDF page size (A4 or LETTER)', 'string'),
 ('reports.email_subject', '"{{companyName}}: {{reportName}} ({{from}} to {{to}})"'::jsonb, 'reports', 'Scheduled report e-mail subject', 'string'),
 ('reports.email_body', '"<p>Good day,</p><p>The scheduled report <b>{{reportName}}</b> for {{from}} to {{to}} is ready ({{rows}} rows, {{format}}).</p><p><a href=\"{{downloadUrl}}\">Download {{fileName}}</a></p><p>{{companyName}}</p>"'::jsonb, 'reports', 'Scheduled report e-mail body (HTML)', 'string'),
 ('reports.claim_ageing_buckets', '[30,60,90,180]'::jsonb, 'reports', 'Claim ageing buckets (days)', 'json'),
 ('reports.claim_open_statuses', '["registered","in-review","pending-approval","approved"]'::jsonb, 'reports', 'Claim statuses counted as open in reports', 'json'),
 ('reports.claim_settled_statuses', '["settled","closed"]'::jsonb, 'reports', 'Claim statuses counted as settled in reports', 'json'),
 ('reports.claim_rejected_statuses', '["rejected"]'::jsonb, 'reports', 'Claim statuses counted as rejected in reports', 'json'),
 ('reports.renewal_retained_statuses', '["renewed"]'::jsonb, 'reports', 'Renewal statuses counted as retained', 'json'),
 ('reports.renewal_lost_statuses', '["lapsed"]'::jsonb, 'reports', 'Renewal statuses counted as lost', 'json'),
 ('reports.trial_balance_statuses', '["approved","posted"]'::jsonb, 'reports', 'Journal voucher statuses included in the trial balance', 'json'),
 ('reports.lead_funnel_stages', '["new","contacted","qualified","quoted","converted","lost"]'::jsonb, 'reports', 'Lead funnel stage order', 'json')
ON CONFLICT (key) DO NOTHING;

